#include <stdio.h>

void trocar(int *a, int *b) {
    int guardado = *a;
    *a = *b;
    *b = guardado;
}

void oInversor(void) {
    int notas[50] = {0};
    int n = 0;

    scanf("%d", &n);

    for (int i = 0; i < n; i++) {
        scanf("%d", &notas[i]);
    }

    for (int i = 0; i < n / 2; i++) {
        trocar(&notas[i], &notas[n - 1 - i]);
    }

    for (int i = 0; i < n; i++) {
        printf("%d\n", notas[i]);
    }
}
